        content: "로게인겔2의 적응증은 안드로젠탈모증(남성형 탈모)이에요. 유전적 요인으로 모낭이 위축되는 유형에만 효과가 있어요. 외용으로 두피에 바르면 모낭 주변 혈류가 늘어나면서 위축됐던 모낭이 다시 성장기로 전환돼요.\n\n효과를 판단하려면 최소 4개월, 가능하면 6개월 이상 꾸준히 사용해야 해요. 초기 1~2개월에는 오히려 빠지는 것처럼 느껴질 수 있는데, 이건 '초기 탈락(쉐딩)' 현상이에요. 휴지기 모발이 성장기 모발에 밀려 나오는 정상 과정이에요.\n\n사용을 중단하면 3~6개월 이내에 원래 탈모 상태로 돌아가요. 로게인겔2은 탈모를 '치료'하는 게 아니라 '억제'하는 약이라서, 효과를 유지하려면 지속 사용이 필수예요. 유전 요인이 없는 탈모, 원형탈모, 출산 관련 탈모에는 효과가 없어요.",
