        content:
          "휴메리나정0.5밀리그램은 (주)휴온스가 만든 두타스테리드(Dutasteride) 성분의 전문의약품이에요. 식약처 허가사항(품목기준코드 202004007)을 보면 두 가지 용도로 허가가 났더라고요. 하나는 양성 전립선 비대증의 치료고, 다른 하나가 성인 남성(만18~50세)의 남성형 탈모(androgenetic alopecia)죠. 모발이 가늘어지고 정수리가 비는 안드로젠탈모증이 바로 이 적응증에 해당해요.\n\n분류는 [02590]기타의 비뇨생식기관 및 항문용약으로 등록돼 있고, 허가 갱신일은 2020년 5월이에요. 약국 진열대에서 바로 집어올 수 있는 약은 아니거든요. 처방전이 필요해요. 피부과나 비뇨기과 진료 후 받게 되는 약이라, 두타스테리드 계열을 한 번쯤 권유받은 분이 많죠. 같은 탈모 목적이라도 임의로 구매할 수 없는 분류라는 점, 먼저 알아두면 좋아요.",
