        "content": "아리드정의 30정 6,000원은 어디까지나 기준가예요. 실제 결제 금액은 약국마다 다를 수 있죠. 전문의약품(식약처 품목번호 200704613)은 약국이 들여오는 매입 단가, 지역, 약국 유형(체인·개인)에 따라 표시가에 차이가 생기거든요. 같은 성분이라도 어느 약국에서 조제받느냐에 따라 몇백 원 단위로 갈릴 수 있어요.\n\n다만 1정당 200원이라는 단가가 동일성분 45개 제품 중 최저가 그룹이라, 약국 간 차이가 있어도 폭이 크진 않아요. 오래 먹을 약이라 이 작은 차이도 누적되면 무시 못 하죠. 매달 6,000원에 단가 차이가 더해지면 해를 거듭할수록 총액이 그만큼 벌어져요. 그래서 한 곳을 정해 계속 조제받는 분이라면, 처음에 단가가 합리적인 약국을 고르는 게 장기적으로 이득이에요. 정확한 약국별 가격은 기준가가 아니라 아래 버튼에서 확인하는 게 맞아요."
