        "content": "이 약을 탈모에 쓰는 근거는 허가증 한 줄에 담겨 있어요. (주)보령이 받은 식약처 허가사항은 보령두타스테리드연질캡슐0.5밀리그램의 대상을 성인 남성(만18~50세)의 남성형 탈모(androgenetic alopecia)로 한정해 뒀어요. '성인 남성'에 더해 '만18~50세'라는 나이 띠가 적응증 안에 같이 박혀 있다는 점, 그게 먼저 확인할 부분이죠.\n\n탈모를 누르는 메커니즘은 호르몬 길목을 끊는 방식이에요. 주성분 두타스테리드 0.5mg이 5알파-환원효소를 붙잡으면, 테스토스테론에서 DHT(디하이드로테스토스테론)로 넘어가는 전환이 줄어들어요. 모낭을 위축시키는 이 DHT를 덜 만들게 하는 셈이죠. 허가사항 적응증엔 양성 전립선 비대증의 증상 개선, 급성 요저류 위험 감소, 수술 필요성 감소도 함께 올라 있어요. 다만 탈모로 처방받을 땐 '얼마나 센가'보다 '내 나이가 품목번호 201906418의 18~50세 안에 드는가'가 먼저예요.",
