        "content": "먹는 방법은 군더더기가 없어요. 식약처 허가사항이 적은 권장용량은 1일 1회 1캡슐(0.5mg), 물과 함께 그대로 넘기면 끝이에요. 밥을 먹었든 안 먹었든 시간대도 가리지 않고, 신장이 약하거나 고령이어도 용량을 깎지 않아요. 단, 연질캡슐은 절대 씹거나 갈라선 안 돼요. 내용물이 새어 입안 점막에 닿으면 자극이 올 수 있다고 허가사항이 명시해요.\n\n핵심은 거르지 않는 거예요. 효소를 누르는 힘은 매일 쌓여야 유지되니까요. 반감기가 길어 하루쯤 늦어도 농도가 급락하진 않지만, 반년 평가선을 채우려면 한 캡슐의 흐름이 끊기면 곤란해요.\n\n쪼개지 말라는 건 효과보다 안전이 걸린 경고예요. 이 성분은 피부로도 들어가서, 임신 중이거나 임신 가능성이 있는 여성이 터진 캡슐 내용물을 만지면 남자 태아의 외부 생식기 형성이 틀어질 수 있다고 허가사항이 짚어요. 간 기능이 나쁜 사람은 권장용량이 세워져 있지 않아, 복용 전 전문의 상의가 먼저예요."
