        "content": "주성분으로는 두타스테리드 0.5mg 한 가지가 들어 있어요. (주)엘앤씨바이오가 제조한 전문의약품이고, 식약처 품목번호는 202001802로 매겨져 있죠. 허가받은 쓰임은 둘이에요. 한쪽이 양성 전립선 비대증 치료, 다른 한쪽이 만 18세부터 50세까지 성인 남성의 남성형 탈모(androgenetic alopecia)고요. 여기서는 탈모 목적으로 먹는 상황에 초점을 맞출게요. 적응증 상한이 50세로 묶여 있어 그 너머 환자의 유효성 자료는 허가사항에 담겨 있지 않고, 여성과 18세 미만 소아는 애초에 투여 금기로 지정돼 있어요. 두타스테리드 0.5mg은 흔한 성분이라 식약처 등재 제품만 45개에 이르는데, 메가두타가 눈에 띄는 까닭은 제형이에요. 단단한 정제가 아니라 물렁한 젤 껍질에 약물이 채워진 연질캡슐로 나온 형태죠. 그래서 이 약을 찾는 분의 질문도 \"어떻게 삼켜야 하나\"로 향해요. 제형이 바뀌면 삼키는 법에도 조건이 붙으니, 복용 순서부터 풀게요.",
