          "짚고 갈 부분이 있어요. 식약처 허가사항에 4년 위약대조 임상시험(PLESS) 결과가 기재돼 있어요. 1,524명에게 이 약을, 1,516명에게 위약을 투여한 시험이에요. 임상 1년차에서 이 약 투여군의 이상반응 수치가 나왔어요.\n\n발기부전은 이 약 8.1%, 위약 3.7%이었고, 성욕감퇴는 이 약 6.4%, 위약 3.4%였어요. 사정액감소는 3.7%(위약 0.8%), 사정장애는 0.8%(위약 0.1%)이었죠. 유방비대와 유방압통도 드물게 보고됐어요.\n\n좋은 소식은 2~4년차에는 발기부전·성욕감퇴·사정장애 발현율이 위약군과 유의한 차이가 없어졌다는 거예요. 그 이후에는 차이가 줄어드는 경향이에요.\n\n시판 후에는 우울증, 우울한 기분, 자살생각 포함 기분변형이 보고됐어요. 식약처 허가 경고 사항에 포함돼 있어요. 이런 정신과적 증상이 나타나면 의료전문가에게 즉시 상담해야 해요. 국내 시판 후 조사에서는 3,675명 중 107명(3.37%)에서 이상반응이 보고됐어요.",
